39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
44	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.service.OwnerAuditLogger;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Maximum number of owners allowed to be registered in a single city. A new owner
66	     * whose city already holds this many owners is rejected as a conflict.
67	     */
68	    private static final long MAX_OWNERS_PER_CITY = 50;
69	
70	    /**
71	     * Maximum number of owners allowed to be registered in a single day. Once this many
72	     * owners already carry today's registration date, a further create is rejected as
73	     * too many requests.
74	     */
75	    private static final long MAX_OWNERS_PER_DAY = 100;
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final TelephoneNormalizer telephoneNormalizer;
86	
87	    private final EmailNormalizer emailNormalizer;
88	
89	    private final AddressNormalizer addressNormalizer;
90	
91	    private final PostcodeValidator postcodeValidator;
92	
93	    private final OwnerAuditLogger ownerAuditLogger;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 EmailNormalizer emailNormalizer,
101	                                 AddressNormalizer addressNormalizer,
102	                                 PostcodeValidator postcodeValidator,
103	                                 OwnerAuditLogger ownerAuditLogger) {
104	        this.clinicService = clinicService;
105	        this.ownerMapper = ownerMapper;
106	        this.petMapper = petMapper;
107	        this.visitMapper = visitMapper;
108	        this.telephoneNormalizer = telephoneNormalizer;
109	        this.emailNormalizer = emailNormalizer;
110	        this.addressNormalizer = addressNormalizer;
111	        this.postcodeValidator = postcodeValidator;
112	        this.ownerAuditLogger = ownerAuditLogger;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        String address = addressNormalizer.normalize(owner.getAddress());
146	        if (addressNormalizer.isBlank(address)) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        owner.setAddress(address);
150	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
151	        if (e164Telephone.isEmpty()) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        String telephone = e164Telephone.get();
155	        String email = emailNormalizer.normalize(owner.getEmail());
156	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
157	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	        }
159	        if (owner.getPostcode() != null && !postcodeValidator.isValid(owner.getPostcode(), owner.getCity())) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
163	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        LocalDate registrationDate = BusinessDay.rollForward(
167	            suppliedRegistrationDate == null ? LocalDate.now() : suppliedRegistrationDate);
168	        owner.setRegistrationDate(registrationDate);
169	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
170	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
171	        }
172	        owner.setTelephone(telephone);
173	        owner.setEmail(email);
174	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
175	            return new ResponseEntity<>(HttpStatus.CONFLICT);
176	        }
177	        // The household is keyed on (last name, postcode): a second owner sharing both is a
178	        // household duplicate and is rejected, unless it declares 'sharesHousehold', which
179	        // bypasses this block and creates it as a (non-suspected) declared household member.
180	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
181	        if (!sharesHousehold && clinicService.isHouseholdOccupied(owner)) {
182	            return new ResponseEntity<>(HttpStatus.CONFLICT);
183	        }
184	        owner.setDeclaredHouseholdMember(sharesHousehold);
185	        this.clinicService.saveOwner(owner);
186	        this.ownerAuditLogger.logCreated(owner);
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        headers.setLocation(UriComponentsBuilder.newInstance()
189	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
190	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
201	        if (e164Telephone.isEmpty()) {
202	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
203	        }
204	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
205	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
206	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
207	        }
208	        String postcode = ownerFieldsDto.getPostcode();
209	        if (postcode != null && !postcodeValidator.isValid(postcode, ownerFieldsDto.getCity())) {
210	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
211	        }
212	        currentOwner.setAddress(ownerFieldsDto.getAddress());
213	        currentOwner.setCity(ownerFieldsDto.getCity());
214	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
215	        currentOwner.setLastName(ownerFieldsDto.getLastName());
216	        currentOwner.setTelephone(e164Telephone.get());
217	        currentOwner.setEmail(email);
218	        currentOwner.setPostcode(postcode);
219	        this.clinicService.saveOwner(currentOwner);
220	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Transactional
225	    @Override
226	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner == null) {
229	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	        }
231	        this.clinicService.deleteOwner(owner);
232	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
238	        Owner owner = this.clinicService.findOwnerById(ownerId);
239	        if (owner == null) {
240	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	        }
242	        HttpHeaders headers = new HttpHeaders();
243	        Pet pet = petMapper.toPet(petFieldsDto);
244	        owner.setId(ownerId);
245	        pet.setOwner(owner);
246	        pet.getType().setName(null);
247	        this.clinicService.savePet(pet);
248	        PetDto petDto = petMapper.toPetDto(pet);
249	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
250	            .buildAndExpand(pet.getId()).toUri());
251	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
257	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
258	        if (currentOwner != null) {
259	            Pet currentPet = this.clinicService.findPetById(petId);
260	            if (currentPet != null) {
261	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
262	                currentPet.setName(petFieldsDto.getName());
263	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
264	                this.clinicService.savePet(currentPet);
265	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
266	            }
267	        }
268	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	    }
270	
271	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
272	    @Override
273	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
274	        HttpHeaders headers = new HttpHeaders();
275	        Visit visit = visitMapper.toVisit(visitFieldsDto);
276	        Pet pet = new Pet();
277	        pet.setId(petId);
278	        visit.setPet(pet);
279	        this.clinicService.saveVisit(visit);
280	        VisitDto visitDto = visitMapper.toVisitDto(visit);
281	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
282	            .buildAndExpand(visit.getId()).toUri());
283	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
284	    }
285	
286	
287	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
288	    @Override
289	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
290	        Owner owner = this.clinicService.findOwnerById(ownerId);
291	        if (owner != null) {
292	            Pet pet = owner.getPet(petId);
293	            if (pet != null) {
294	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
295	            }
296	        }
297	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
298	    }
299	}
