33	/**
34	 * Mostly used as a facade so all controllers have a single point of entry
35	 *
36	 * @author Michael Isvy
37	 * @author Vitaliy Fedoriv
38	 */
39	public interface ClinicService {
40	
41		Pet findPetById(int id) throws DataAccessException;
42		Collection<Pet> findAllPets() throws DataAccessException;
43	    Page<Pet> findPets(Pageable pageable) throws DataAccessException;
44		void savePet(Pet pet) throws DataAccessException;
45		void deletePet(Pet pet) throws DataAccessException;
46	
47		Collection<Visit> findVisitsByPetId(int petId);
48		Visit findVisitById(int visitId) throws DataAccessException;
49		Collection<Visit> findAllVisits() throws DataAccessException;
50		void saveVisit(Visit visit) throws DataAccessException;
51		void deleteVisit(Visit visit) throws DataAccessException;
52		Vet findVetById(int id) throws DataAccessException;
53		Collection<Vet> findVets() throws DataAccessException;
54		Collection<Vet> findAllVets() throws DataAccessException;
55		void saveVet(Vet vet) throws DataAccessException;
56		void deleteVet(Vet vet) throws DataAccessException;
57		Owner findOwnerById(int id) throws DataAccessException;
58		Collection<Owner> findAllOwners() throws DataAccessException;
59		Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException;
60		void saveOwner(Owner owner) throws DataAccessException;
61		void deleteOwner(Owner owner) throws DataAccessException;
62		Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException;
63	
64		/**
65		 * Check whether an existing owner already occupies the given owner's household, i.e.
66		 * whether another owner shares its last name and postcode (its computed household id).
67		 * Used to reject a new owner as a household duplicate unless it declares it shares the
68		 * household.
69		 *
70		 * @param owner the owner about to be created
71		 * @return <code>true</code> if at least one existing owner already occupies that household
72		 */
73		boolean isHouseholdOccupied(Owner owner) throws DataAccessException;
74	
75		/**
76		 * Count the <code>Owner</code>s already registered in the given city, compared
77		 * case-insensitively.
78		 *
79		 * @param city the city to match (case-insensitively)
80		 * @return the number of owners already living in that city
81		 */
82		long countOwnersByCity(String city) throws DataAccessException;
83	
84		/**
85		 * Count the <code>Owner</code>s registered on the given date. Used to enforce the
86		 * daily cap on how many owners may be created in a single day.
87		 *
88		 * @param registrationDate the registration date to match
89		 * @return the number of owners registered on that date
90		 */
91		long countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException;
92	
93		PetType findPetTypeById(int petTypeId);
94		Collection<PetType> findAllPetTypes() throws DataAccessException;
95		Collection<PetType> findPetTypes() throws DataAccessException;
96		void savePetType(PetType petType) throws DataAccessException;
97		void deletePetType(PetType petType) throws DataAccessException;
98		Specialty findSpecialtyById(int specialtyId);
99		Collection<Specialty> findAllSpecialties() throws DataAccessException;
100		void saveSpecialty(Specialty specialty) throws DataAccessException;
101		void deleteSpecialty(Specialty specialty) throws DataAccessException;
102	
103	    List<Specialty> findSpecialtiesByNameIn(Set<String> names) throws DataAccessException;
104	}
