247	    @Override
248	    @Transactional
249	    public void saveOwner(Owner owner) throws DataAccessException {
250	        if (owner.isNew()) {
251	            if (owner.getCustomerCode() == null) {
252	                owner.setCustomerCode(customerCodeGenerator.generate(
253	                    RegionResolver.regionFor(owner.getPostcode(), owner.getCity()),
254	                    owner.getTelephone(), owner.getLastName()));
255	            }
256	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
257	            owner.setBulkSignupWarning(
258	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
259	            owner.setHouseholdId(householdIdFor(owner));
260	            owner.setHouseholdSize(householdSizeIncluding(owner));
261	            Optional<Owner> possibleDuplicate = findPossibleDuplicate(owner);
262	            owner.setPossibleDuplicate(possibleDuplicate.isPresent());
263	            owner.setPossibleDuplicateOf(possibleDuplicate.map(Owner::getId).orElse(null));
264	        }
265	        ownerRepository.save(owner);
266	
267	    }
