269	    /**
270	     * The deterministic, shared household id this owner maps to, derived from its last
271	     * name and postcode so that owners sharing both belong to the same household.
272	     */
273	    private String householdIdFor(Owner owner) {
274	        return householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
275	    }
276	
277	    /**
278	     * Size of the household this new owner will belong to once persisted: the owners
279	     * already sharing its household id, plus the owner itself. An owner with no shared
280	     * household id stands alone, so its household size is one.
281	     */
282	    private int householdSizeIncluding(Owner owner) {
283	        if (owner.getHouseholdId() == null) {
284	            return 1;
285	        }
286	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
287	    }
288	
289	    /**
290	     * Count the existing owners that already share the given first and last name,
291	     * compared case-insensitively. Used to stamp a new owner's namesake count at
292	     * registration, before it is itself persisted.
293	     */
294	    private int countNamesakes(String firstName, String lastName) {
295	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
296	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
297	            .count();
298	    }
299	
300	    /**
301	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate
302	     * of: one that occupies the same household (the same computed household id) but carries
303	     * a different telephone, so it is not a hard duplicate. When several match, the earliest
304	     * (lowest id) is chosen. An owner that belongs to no household (no household id), or one
305	     * that deliberately declared it shares a household, is never a suspected duplicate.
306	     */
307	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
308	        String householdId = owner.getHouseholdId();
309	        if (householdId == null || owner.isDeclaredHouseholdMember()) {
310	            return Optional.empty();
311	        }
312	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
313	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
314	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
315	            .min(Comparator.comparing(Owner::getId));
316	    }
