17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Locale;
20	import java.util.Set;
21	import java.util.regex.Pattern;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Normalizes and validates an owner's email address. An email is optional, but
27	 * when supplied it must be a syntactically valid address; it is stored and
28	 * returned lower-cased.
29	 */
30	@Component
31	public class EmailNormalizer {
32	
33	    private static final Pattern EMAIL_PATTERN =
34	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
35	
36	    /**
37	     * Domains of disposable/throwaway email providers that are not accepted as an
38	     * owner's email address.
39	     */
40	    private static final Set<String> DISPOSABLE_DOMAINS =
41	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
42	
43	    /**
44	     * Lower-case the given email, trimming surrounding whitespace.
45	     *
46	     * @param email the raw email value (may be {@code null})
47	     * @return the normalized email, or {@code null} if {@code email} is {@code null}
48	     */
49	    public String normalize(String email) {
50	        return email == null ? null : email.trim().toLowerCase(Locale.ROOT);
51	    }
52	
53	    /**
54	     * @param email an email value (typically already normalized)
55	     * @return {@code true} if it is a syntactically valid email address
56	     */
57	    public boolean isValid(String email) {
58	        return email != null && EMAIL_PATTERN.matcher(email).matches();
59	    }
60	
61	    /**
62	     * @param email an email value (typically already normalized)
63	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
64	     */
65	    public boolean isDisposable(String email) {
66	        if (email == null) {
67	            return false;
68	        }
69	        int at = email.lastIndexOf('@');
70	        if (at < 0) {
71	            return false;
72	        }
73	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
74	        return DISPOSABLE_DOMAINS.contains(domain);
75	    }
76	}
