16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Locale;
19	
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Builds an owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where
24	 * REGION is the owner's canonical region (see
25	 * {@link org.springframework.samples.petclinic.model.RegionResolver}) and HASH8 is the
26	 * first eight upper-case hexadecimal characters of the SHA-256 hash over the owner's
27	 * normalized telephone followed by its last name. The identity is derived purely from
28	 * the owner's own fields, carrying no sequence number.
29	 */
30	@Component
31	public class CustomerCodeGenerator {
32	
33	    private static final int HASH_LENGTH = 8;
34	
35	    /**
36	     * Build the customer code for a new owner.
37	     *
38	     * @param region             the owner's canonical region
39	     * @param normalizedTelephone the owner's normalized (E.164) telephone
40	     * @param lastName           the owner's last name
41	     * @return the formatted customer code, e.g. {@code "NSW-1A2B3C4D"}
42	     */
43	    public String generate(String region, String normalizedTelephone, String lastName) {
44	        return region + "-" + hash8(normalizedTelephone, lastName);
45	    }
46	
47	    private String hash8(String normalizedTelephone, String lastName) {
48	        String identity = safe(normalizedTelephone) + safe(lastName);
49	        return Sha256.hex(identity).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
50	    }
51	
52	    private String safe(String value) {
53	        return value == null ? "" : value;
54	    }
55	}
